    public companion object {
        /**
         * Subscribes to every stream, in CipherAddEdit's numbering, and builds the model from what they replay. Each message
         * is decoded whole, then applied (the connection checks every byte was read in between).
         *
         * @throws OahuContractException when a state stream replays nothing; the connection is closed first, so the
         *   provider refuses the screen with nothing left subscribed.
         */
        public fun connect(port: Port): CipherAddEditModel {
            val connection = OahuConnection(port)
            try {
                val copy = connection.subscribeState(
                    CipherAddEditContract.STREAM_COPY,
                    CipherAddEditCopyOahuCodec::readCipherAddEditCopy,
                )
                val palette = connection.subscribeState(
                    CipherAddEditContract.STREAM_PALETTE,
                    AppPaletteOahuCodec::readAppPalette,
                )
                val layout = connection.subscribeState(
                    CipherAddEditContract.STREAM_LAYOUT,
                    CipherAddEditLayoutOahuCodec::readCipherAddEditLayout,
                )
                val choices = connection.subscribeState(
                    CipherAddEditContract.STREAM_CHOICES,
                    CipherAddEditChoicesOahuCodec::readCipherAddEditChoices,
                )
                val type = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_TYPE,
                    CipherAddEditContract.MEMBER_EDIT_TYPE,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val folder = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_FOLDER,
                    CipherAddEditContract.MEMBER_EDIT_FOLDER,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val owner = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_OWNER,
                    CipherAddEditContract.MEMBER_EDIT_OWNER,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val cardBrand = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARD_BRAND,
                    CipherAddEditContract.MEMBER_EDIT_CARD_BRAND,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val cardExpMonth = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARD_EXP_MONTH,
                    CipherAddEditContract.MEMBER_EDIT_CARD_EXP_MONTH,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val identityTitle = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_IDENTITY_TITLE,
                    CipherAddEditContract.MEMBER_EDIT_IDENTITY_TITLE,
                    OahuReader::readInt,
                    OahuWriter::writeInt,
                )
                val name = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_NAME,
                    CipherAddEditContract.MEMBER_EDIT_NAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val username = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_USERNAME,
                    CipherAddEditContract.MEMBER_EDIT_USERNAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val password = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_PASSWORD,
                    CipherAddEditContract.MEMBER_EDIT_PASSWORD,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val totp = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_TOTP,
                    CipherAddEditContract.MEMBER_EDIT_TOTP,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val cardholderName = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARDHOLDER_NAME,
                    CipherAddEditContract.MEMBER_EDIT_CARDHOLDER_NAME,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val cardNumber = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARD_NUMBER,
                    CipherAddEditContract.MEMBER_EDIT_CARD_NUMBER,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val cardExpYear = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARD_EXP_YEAR,
                    CipherAddEditContract.MEMBER_EDIT_CARD_EXP_YEAR,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val cardCode = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_CARD_CODE,
                    CipherAddEditContract.MEMBER_EDIT_CARD_CODE,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val notes = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_NOTES,
                    CipherAddEditContract.MEMBER_EDIT_NOTES,
                    OahuReader::readString,
                    OahuWriter::writeString,
                )
                val identity = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_IDENTITY,
                    CipherAddEditContract.MEMBER_EDIT_IDENTITY,
                    IdentityFieldsOahuCodec::readIdentityFields,
                    IdentityFieldsOahuCodec::writeIdentityFields,
                )
                val favorite = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_FAVORITE,
                    CipherAddEditContract.MEMBER_EDIT_FAVORITE,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val reprompt = connection.subscribeEditable(
                    CipherAddEditContract.STREAM_REPROMPT,
                    CipherAddEditContract.MEMBER_EDIT_REPROMPT,
                    OahuReader::readBool,
                    OahuWriter::writeBool,
                )
                val uris = KeyedList(EditUriRow::key)
                connection.subscribe(
                    CipherAddEditContract.STREAM_URIS,
                    { it.readBatch(EditUriRowOahuCodec::readEditUriRow) },
                    uris::apply,
                )
                val fields = KeyedList(EditFieldRow::key)
                connection.subscribe(
                    CipherAddEditContract.STREAM_FIELDS,
                    { it.readBatch(EditFieldRowOahuCodec::readEditFieldRow) },
                    fields::apply,
                )
                val collections = KeyedList(CollectionCheckRow::key)
                connection.subscribe(
                    CipherAddEditContract.STREAM_COLLECTIONS,
                    { it.readBatch(CollectionCheckRowOahuCodec::readCollectionCheckRow) },
                    collections::apply,
                )
                val focus = OahuEvents<FormFocus>()
                connection.subscribe(CipherAddEditContract.STREAM_FOCUS, FormFocusOahuCodec::readFormFocus, focus::emit)
                return CipherAddEditModel(
                    connection,
                    copy,
                    palette,
                    layout,
                    choices,
                    type,
                    folder,
                    owner,
                    cardBrand,
                    cardExpMonth,
                    identityTitle,
                    name,
                    username,
                    password,
                    totp,
                    cardholderName,
                    cardNumber,
                    cardExpYear,
                    cardCode,
                    notes,
                    identity,
                    favorite,
                    reprompt,
                    uris,
                    fields,
                    collections,
                    focus,
                )
            } catch (failure: Throwable) {
                connection.close()
                throw failure
            }
        }

        /**
         * The real model over an [OahuPreviewPort] that replays these values. Methods without handlers
         * have no effect. [configure] runs on a [Preview] before the model connects.
         */
        public fun preview(
            copy: CipherAddEditCopy,
            palette: AppPalette,
            layout: CipherAddEditLayout,
            choices: CipherAddEditChoices,
            type: Int,
            folder: Int,
            owner: Int,
            cardBrand: Int,
            cardExpMonth: Int,
            identityTitle: Int,
            name: String,
            username: String,
            password: String,
            totp: String,
            cardholderName: String,
            cardNumber: String,
            cardExpYear: String,
            cardCode: String,
            notes: String,
            identity: IdentityFields,
            favorite: Boolean,
            reprompt: Boolean,
            uris: List<EditUriRow> = emptyList(),
            fields: List<EditFieldRow> = emptyList(),
            collections: List<CollectionCheckRow> = emptyList(),
            configure: Preview.() -> Unit = {},
        ): CipherAddEditModel {
            val port = OahuPreviewPort(CipherAddEditContract.NAME, CipherAddEditContract.HASH)
            port.setState(CipherAddEditContract.STREAM_COPY) { CipherAddEditCopyOahuCodec.writeCipherAddEditCopy(it, copy) }
            port.setState(CipherAddEditContract.STREAM_PALETTE) { AppPaletteOahuCodec.writeAppPalette(it, palette) }
            port.setState(CipherAddEditContract.STREAM_LAYOUT) { CipherAddEditLayoutOahuCodec.writeCipherAddEditLayout(it, layout) }
            port.setState(CipherAddEditContract.STREAM_CHOICES) { CipherAddEditChoicesOahuCodec.writeCipherAddEditChoices(it, choices) }
            port.setState(CipherAddEditContract.STREAM_TYPE) { it.writeInt(type) }
            port.setState(CipherAddEditContract.STREAM_FOLDER) { it.writeInt(folder) }
            port.setState(CipherAddEditContract.STREAM_OWNER) { it.writeInt(owner) }
            port.setState(CipherAddEditContract.STREAM_CARD_BRAND) { it.writeInt(cardBrand) }
            port.setState(CipherAddEditContract.STREAM_CARD_EXP_MONTH) { it.writeInt(cardExpMonth) }
            port.setState(CipherAddEditContract.STREAM_IDENTITY_TITLE) { it.writeInt(identityTitle) }
            port.setState(CipherAddEditContract.STREAM_NAME) { it.writeString(name) }
            port.setState(CipherAddEditContract.STREAM_USERNAME) { it.writeString(username) }
            port.setState(CipherAddEditContract.STREAM_PASSWORD) { it.writeString(password) }
            port.setState(CipherAddEditContract.STREAM_TOTP) { it.writeString(totp) }
            port.setState(CipherAddEditContract.STREAM_CARDHOLDER_NAME) { it.writeString(cardholderName) }
